SELECT progress_id
FROM lecture_progress
WHERE user_id = #{userId}
AND lecture_id = #{lectureId}

SELECT completed_yn = 'Y'
FROM lecture_progress
WHERE user_id = #{userId}
AND lecture_id = #{lectureId}

SELECT COALESCE(last_watched_time, 0)
FROM lecture_progress
WHERE user_id = #{userId}
AND lecture_id = #{lectureId}

mapper.update:

UPDATE lecture_progress
SET last_watched_time = #{lastWatchedTime},
updated_at = NOW()
WHERE user_id = #{userId}
AND lecture_id = #{lectureId}
AND last_watched_time < #{lastWatchedTime}
